for fn in ['Correspondence/DSR_Ph3_Resubmittal_Tracker.xlsx','Correspondence/Agency/DSR_Ph3_Transmittal_Clearance_Log.xlsx','Design-Drafting/Landscape/DSR_Ph3_Turf_Planting_Tabulation.xlsx','Design-Drafting/Phase 3/DSR_Ph3_QAQC_Checklist.xlsx']:
 print('\n###',fn)
 z=zipfile.ZipFile(fn); ns={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
 ss=[]
 if 'xl/sharedStrings.xml' in z.namelist():
  root=ET.fromstring(z.read('xl/sharedStrings.xml')); ss=[''.join(x.itertext()) for x in root.findall('m:si',ns)]
 wb=ET.fromstring(z.read('xl/workbook.xml')); rel=ET.fromstring(z.read('xl/_rels/workbook.xml.rels')); rns={'r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
 rels={x.attrib['Id']:x.attrib['Target'] for x in rel}
 for sh in wb.find('m:sheets',ns):
  target='xl/'+rels[sh.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']]
  if not target.endswith('.xml'): target=target+'.xml'
  root=ET.fromstring(z.read(target)); print('SHEET',sh.attrib['name'])
  for row in root.findall('.//m:sheetData/m:row',ns):
   vals=[]
   for c in row.findall('m:c',ns):
    v=c.find('m:v',ns); val='' if v is None else v.text
    if c.attrib.get('t')=='s' and val: val=ss[int(val)]
    vals.append(f"{c.attrib.get('r')}={val}")
   if vals: print(' | '.join(vals))
